'use strict';
let channelCatalog={channels:[],videos:[]},channelGenre='すべて',channelFormat='すべて',channelOrigin='all',channelQuery='',channelLevel='all';
function validChannelCatalog(c){return !!(c&&Array.isArray(c.channels)&&Array.isArray(c.videos)&&c.channels.every(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&typeof x.url==='string'&&Array.isArray(x.tags)&&Array.isArray(x.formats)&&Array.isArray(x.articles)&&Array.isArray(x.rooms))&&c.videos.every(v=>v&&typeof v.id==='string'&&typeof v.channel==='string'&&typeof v.url==='string'))}
function channelById(id){return channelCatalog.channels.find(c=>c.id===id)}
function channelMatches(c){return(channelGenre==='すべて'||c.tags.includes(channelGenre))&&(channelFormat==='すべて'||c.formats.includes(channelFormat))&&(channelOrigin==='all'||(channelOrigin==='favorite'?c.origin==='favorite':channelOrigin==='saved'?(state.channelSaves||[]).includes(c.id):c.origin==='discovery'))&&(!channelQuery||[c.name,c.description,c.catch,c.entry,...c.tags,...c.formats].join(' ').toLowerCase().includes(channelQuery.toLowerCase()))}
function channelTeaser(){if(!channelCatalog.channels.length)return '';return `<section class="channel-teaser"><div><div class="eyebrow">THE CURIOSITY TUNER</div><h2>好きな語り手から、<br>知らなかった世界へ。</h2><p>いつもの12チャンネルと、新しい18の入口。<br>映像、図解、対談。今日はどんな気分？</p><a class="primary" href="#channels">チャンネルを探検する</a></div><div class="tuner-dial" aria-hidden="true"><div class="tuner-orbit"></div><span>WATCH<br>LISTEN<br>WONDER</span><i></i><b>好奇心を、合わせよう。</b></div></section>`}
function mediaNavigation(active){return `<div class="media-navigation" aria-label="映像の探検メニュー"><a href="#channels" ${active==='channels'?'aria-current="page"':''}>語り手から探す</a><a href="#watch" ${active==='watch'?'aria-current="page"':''}>最初の一本から</a><a href="#videos" ${active==='videos'?'aria-current="page"':''}>展示の参考動画</a></div>`}
function channelRow(c){const saved=(state.channelSaves||[]).includes(c.id);const starters=channelCatalog.videos.filter(v=>v.channel===c.id);return `<article class="channel-row" data-channel-row="${c.id}"><div class="channel-glyph" aria-hidden="true">${esc(c.name.slice(0,2))}</div><div class="channel-copy"><p class="channel-kicker">${c.origin==='favorite'?'好きなチャンネルから':'新しい出会い'} · ${esc(c.tags.join(' / '))}</p><h2><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.name)}</a></h2><p class="channel-catch">${esc(c.catch)}</p><p>${esc(c.description)}</p><div class="channel-formats">${c.formats.map(f=>`<span>${esc(f)}</span>`).join('')}</div><details><summary>選ぶヒントと、次の寄り道</summary><p>${esc(c.entry)}</p><p class="fine">${esc(c.note)}</p><div class="channel-connections">${c.articles.map(id=>{const a=data.find(a=>a.id===id);return a?`<button class="text-link" data-article="${id}">${esc(a.title)}</button>`:''}).join('')}${c.rooms.map(id=>{const r=ROOMS.find(r=>r.id===id);return r?`<a href="#room-${id}">${esc(r.short)}の展示室</a>`:''}).join('')}</div><p class="fine">チャンネル情報の確認：${esc(c.checked)}。この紹介と関連付けはラボの編集です。</p></details><div class="channel-actions"><a class="primary" href="${esc(c.url)}" target="_blank" rel="noopener">YouTubeで開く</a>${starters.length?`<a class="secondary" href="#watch-${c.id}">入口の動画を見る</a>`:''}<button class="secondary" data-channel-save="${c.id}" aria-pressed="${saved}">${saved?'保存済み':'チャンネルを保存'}</button><button class="text-link" data-channel-bridge="${c.id}">GPTへの問いをコピー</button></div></div></article>`}
function channelPage(){const tags=[...new Set(channelCatalog.channels.flatMap(c=>c.tags))];return `<div class="page channel-page">${mediaNavigation('channels')}<section class="channel-cover"><div class="eyebrow">YOUR FIELD GUIDE TO CURIOUS MINDS</div><h1>好奇心に、<br>チャンネルを合わせる。</h1><p>好きな語り手をたどる日も、<br>知らない分野をのぞく日も。</p><div class="channel-cover-meta"><span>${channelCatalog.channels.length} CHANNELS</span><span>日本語で楽しむ探検ガイド</span></div></section><div class="channel-controls"><label for="channel-search">名前・テーマで探す<input id="channel-search" type="search" value="${esc(channelQuery)}" placeholder="宇宙、哲学、ツール、対談…"></label><div class="channel-selects"><label>気になる分野<select id="channel-genre">${['すべて',...tags].map(t=>`<option ${channelGenre===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>今日はどんな気分？<select id="channel-format">${['すべて','図解で見る','実物で見る','対談を聞く','じっくり学ぶ'].map(t=>`<option ${channelFormat===t?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="channel-origin">${[['all','すべて'],['favorite','好きなチャンネルから'],['discovery','新しい出会い'],['saved','保存したチャンネル']].map(([id,label])=>`<button data-channel-origin="${id}" aria-pressed="${channelOrigin===id}">${label}</button>`).join('')}<button data-channel-random>偶然のチャンネルへ</button></div></div><div id="channel-results">${channelResults()}</div><aside class="channel-editor-note"><h2>紹介は、入口。確かめる道も、一緒に。</h2><p>チャンネル全体の内容を採点したり、正しさを保証したりする一覧ではありません。対談の意見、仮説、観測された事実を区別しながら楽しめるよう、展示と日本語の参考資料へ戻る道を添えています。</p><p>「最初の一本」は個別に題名・公開元を確認した動画です。全編の実視聴評価は未完了のため、点数や人気順位は付けていません。</p></aside></div>`}
function channelResults(){const items=channelCatalog.channels.filter(channelMatches);return `<p class="channel-result-count" role="status">条件に合う ${items.length} チャンネル${channelOrigin==='saved'?' · 保存全'+(state.channelSaves||[]).length+'件':''}</p>${items.map(channelRow).join('')||'<div class="empty"><h2>別の入口も、のぞいてみませんか。</h2><p>検索条件を変えるか、気になるチャンネルを保存してください。</p><button class="secondary" data-channel-reset>条件をリセット</button></div>'}`}
function refreshChannelResults(){const el=$('#channel-results');if(el)el.innerHTML=channelResults()}
function channelBridge(c){return `【Curiosity Lab：チャンネルからの寄り道】\nチャンネル：${c.name}\nURL：${c.url}\n扱うテーマ：${c.tags.join('、')}\n紹介：${c.description}\nラボが提案する入口：${c.entry}\n関連展示と日本語出典：\n${c.articles.map(id=>{const a=data.find(a=>a.id===id);return a?a.title+'\n'+a.sources.map(s=>s.name+' '+s.url).join('\n'):''}).join('\n')}\n依頼：この分野をもっと楽しむための問いを3つと、関連する別分野への寄り道を提案してください。リンク先の動画を視聴済みだとは仮定せず、内容の断定や引用は避け、確認できる事実と提案を分けてください。創作への転用は私が判断します。`}
function articleChannels(a){const items=channelCatalog.channels.filter(c=>c.articles.includes(a.id));if(!items.length)return '';return `<section class="article-channel-links"><div class="eyebrow">FOLLOW ANOTHER VOICE</div><h2>別の語り手と、寄り道する。</h2><p>この動画で記事の内容を検証した、という意味ではなく、関心がつながるチャンネルの案内です。</p>${items.slice(0,3).map(c=>`<div><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.name)}</a><p>${esc(c.catch)}</p></div>`).join('')}<a class="text-link" href="#channels">チャンネルガイドを見る</a></section>`}
function watchPage(channelId){const channel=channelById(channelId);let videos=channelCatalog.videos.filter(v=>(!channel||v.channel===channel.id)&&(channelLevel==='all'||v.level===channelLevel));return `<div class="page">${mediaNavigation('watch')}<div class="eyebrow">ONE FILM, ANOTHER QUESTION</div><h1 class="route-title">最初の一本から、<br>世界を広げる。</h1><p class="route-intro">${channel?esc(channel.name)+'の入口。':'どこから見ようか迷ったら、テーマを一つ。'}<br>動画のあとには、ラボの展示や日本語の資料へ。</p><div class="channel-origin">${['all','はじめの一本','さらに深く'].map(l=>`<button data-watch-level="${l}" aria-pressed="${channelLevel===l}">${l==='all'?'すべて':l}</button>`).join('')}${channel?'<a href="#watch">すべての入口に戻る</a>':''}</div><p class="fine">${channelCatalog.videos.length}本の編集選定。字幕・公開状態は配信元で変わる場合があります。全編評価は未完了です。</p><div class="video-grid">${videos.map(v=>videoCard({...v,image:data.find(a=>a.id===v.articleId)?.image})).join('')||'<p class="empty">この条件の動画は準備中です。別の条件でも探してみてください。</p>'}</div></div>`}
function toggleChannelSave(id){if(!channelById(id))return;const before=state.channelSaves||[];state.channelSaves=before.includes(id)?before.filter(x=>x!==id):[...before,id];if(!persist()){state.channelSaves=before;return}refreshChannelResults();toast(state.channelSaves.includes(id)?'チャンネルを保存しました':'チャンネルの保存を解除しました')}
document.addEventListener('input',e=>{if(e.target.id==='channel-search'){channelQuery=e.target.value;refreshChannelResults()}});
document.addEventListener('change',e=>{if(e.target.id==='channel-genre'){channelGenre=e.target.value;refreshChannelResults()}if(e.target.id==='channel-format'){channelFormat=e.target.value;refreshChannelResults()}});
document.addEventListener('click',e=>{let b=e.target.closest('[data-channel-save]');if(b){toggleChannelSave(b.dataset.channelSave);return}b=e.target.closest('[data-channel-bridge]');if(b){const c=channelById(b.dataset.channelBridge);if(c)copy(channelBridge(c));return}b=e.target.closest('[data-channel-origin]');if(b){channelOrigin=b.dataset.channelOrigin;render();return}if(e.target.closest('[data-channel-reset]')){channelQuery='';channelGenre=channelFormat='すべて';channelOrigin='all';render();return}if(e.target.closest('[data-channel-random]')){const items=channelCatalog.channels.filter(channelMatches);if(!items.length){toast('条件に合うチャンネルがありません');return}channelQuery=items[Math.floor(Math.random()*items.length)].name;render();$('#channel-results')?.scrollIntoView({behavior:'smooth'});return}b=e.target.closest('[data-watch-level]');if(b){channelLevel=b.dataset.watchLevel;render()}});
